mapper.update:
UPDATE settlement_batch
SET status = #{status}
    , failure_message = #{failureMessage}
WHERE batch_id = #{batchId}
  AND status = 'RUNNING'
  AND #{status} IN ('COMPLETED', 'FAILED')
